"""
Agent type definitions and permission checking.

Defines what each agent type can do:
- Leader: can message anyone, assign tasks, create teams
- Worker: messages parent/leader only, executes tasks
- Observer: read-only, monitors sessions
- Reviewer: can approve/reject, messages team members
"""

from .constants import AGENT_PERMISSIONS


def get_permissions(agent_type: str) -> dict:
    """Return the permission profile for an agent type.

    Falls back to worker permissions if the type is unknown.
    """
    return AGENT_PERMISSIONS.get(agent_type, AGENT_PERMISSIONS.get("worker", {}))


def can_message(
    sender_type: str,
    target_type: str,
    same_team: bool = False,
    is_parent: bool = False,
) -> bool:
    """Check if a sender agent type can message a target agent type.

    Args:
        sender_type: The agent type of the sender.
        target_type: The agent type of the target.
        same_team: Whether sender and target share a team_id.
        is_parent: Whether target is the sender's parent session.
    """
    perms = get_permissions(sender_type)
    scope = perms.get("can_message", "none")

    if scope == "any":
        return True
    if scope == "none":
        return False
    if scope == "parent_and_leader":
        return is_parent or (target_type == "leader" and same_team)
    if scope == "team":
        return same_team
    return False


def can_assign_tasks(agent_type: str) -> bool:
    """Check if agent type can assign tasks to other agents."""
    return get_permissions(agent_type).get("can_assign_tasks", False)


def can_create_teams(agent_type: str) -> bool:
    """Check if agent type can create teams."""
    return get_permissions(agent_type).get("can_create_teams", False)
